/// Parallel batch processing pipeline powered by Rayon across all CPU cores
pub fn run_batch_parallel(batch: &mut [StateNC101A]) {
    batch.par_iter_mut().for_each(|state| {
        state.p_0000_procedure_start();
    });
}
